// Some portions generated by Claude
'use strict';
const test = require('node:test');
const assert = require('node:assert/strict');

const graphAdditions = require(require('./workbench-scripts.js').workbenchScriptPath('graphAdditions.js'));

// "Add to graph" on the Workbench pages queues resources, statements and queries for the Graph page of the same
// repository, which takes them when it opens (see tools/workbench/src/main/frontend/graph-explorer/graph-additions.ts).
function memoryStorage() {
    const values = new Map();
    return {
        getItem: (key) => (values.has(key) ? values.get(key) : null),
        setItem: (key, value) => values.set(key, String(value)),
        removeItem: (key) => values.delete(key),
        values
    };
}

const context = { basePath: '/wb/', repositoryId: 'my repo' };

test('a resource is queued under the repository of the page', () => {
    const storage = memoryStorage();
    assert.equal(graphAdditions.add(context, { kind: 'resource', term: '<urn:a>' }, storage), 1);
    assert.deepEqual([...storage.values.keys()], ['rdf4j-workbench-graph-additions:/wb|my repo']);
    assert.deepEqual(graphAdditions.pending(context, storage), [{ kind: 'resource', term: '<urn:a>' }]);
});

test('the same addition is queued once, statements and queries alongside resources', () => {
    const storage = memoryStorage();
    graphAdditions.add(context, { kind: 'resource', term: '<urn:a>' }, storage);
    graphAdditions.add(context, [
        { kind: 'resource', term: '<urn:a>' },
        { kind: 'statement', subject: '<urn:a>', predicate: '<urn:p>', object: '"x"@en' },
        { kind: 'query', query: 'CONSTRUCT WHERE { ?s ?p ?o } LIMIT 5' }
    ], storage);
    assert.deepEqual(graphAdditions.pending(context, storage).map((entry) => entry.kind), ['resource', 'statement', 'query']);
});

test('malformed entries and unreadable storage are ignored', () => {
    const storage = memoryStorage();
    assert.equal(graphAdditions.add(context, { kind: 'resource', term: 'not a term' }, storage), 0);
    assert.equal(graphAdditions.add(context, { kind: 'nonsense' }, storage), 0);
    storage.setItem('rdf4j-workbench-graph-additions:/wb|my repo', '{broken');
    assert.deepEqual(graphAdditions.pending(context, storage), []);
    const failing = { getItem() { throw new Error('denied'); }, setItem() { throw new Error('denied'); } };
    assert.equal(graphAdditions.add(context, { kind: 'resource', term: '<urn:a>' }, failing), 0);
});

test('the queue keeps the newest 500 additions', () => {
    const storage = memoryStorage();
    const entries = Array.from({ length: 510 }, (_, index) => ({ kind: 'resource', term: `<urn:r${index}>` }));
    assert.equal(graphAdditions.add(context, entries, storage), 500);
    const pending = graphAdditions.pending(context, storage);
    assert.equal(pending[0].term, '<urn:r10>');
    assert.equal(pending[499].term, '<urn:r509>');
});

test('the Graph page of the repository', () => {
    assert.equal(graphAdditions.graphUrl(context), '/wb/repositories/my%20repo/graph');
});
